import json,re,sys
base=sys.argv[1]
tax=json.load(open(base+'/taxonomy.json'))
inp={x['id']:x for x in json.load(open(base+'/inputs.json'))}
ids=['Q%d'%i for i in range(49,57)]
def strings(o):
    if isinstance(o,str): yield o
    elif isinstance(o,dict):
        for v in o.values(): yield from strings(v)
    elif isinstance(o,list):
        for v in o: yield from strings(v)
for i in ids:
    d=json.load(open(f'{base}/verified/{i}.json'))
    errs=[]
