    if set(v)!={'status','changes','residualConcerns','spotCheckPriority'}: errs.append('verif keys')
    for s in strings(d):
        if '—' in s: errs.append('emdash')
        if re.search(r';0:|0\(0\)|Vol 00',s): errs.append('placeholder')
    if d['decision']=='INCLUDE':
        if d['studyDesign'] not in tax['studyDesigns']: errs.append('design')
